/* int32-domain bitwise helpers: boxed Janet errors outside int32
 * (integral doubles accepted); results wrap int32; shift counts mask
 * to 5 bits. Callers range/integrality-check operands (fail loud). */
static int32_t k_band32(int32_t a, int32_t b) { return a & b; }
static int32_t k_bor32(int32_t a, int32_t b) { return a | b; }
static int32_t k_bxor32(int32_t a, int32_t b) { return a ^ b; }
static int32_t k_sl32(int32_t a, int32_t b) { return (int32_t)((uint32_t)a << ((uint32_t)b & 31u)); }
static int32_t k_sr32(int32_t a, int32_t b) { uint32_t n = (uint32_t)b & 31u; int32_t r = (int32_t)((uint32_t)a >> n); if ((a < 0) && (n != 0)) { r |= (int32_t)(~0u << (32u - n)); } return r; }
static int32_t k_sru32(int32_t a, int32_t b) { return (int32_t)((uint32_t)a >> ((uint32_t)b & 31u)); }


int64_t block_index(int64_t p0, int64_t p1, int64_t p2) {
    int64_t s3;
    int64_t s4;
    uint64_t s5;
    s3 = 16;
    s4 = s3 * p1;
    s3 = p2 + s4;
    s5 = 16;
    s4 = s5 * s3;
    s3 = p0 + s4;
    return s3;
}
