/* Native FFI aliases (ffi/defbind-alias). Wrappers convert arguments
 * with the boxed marshaller's own getters, call the C function through
 * a statically typed pointer, and box the result with the marshaller's
 * read rules. The pointer is resolved lazily through the alias's
 * original lookup thunk, so the library still loads only at first use. */
static Janet ffi_box_i64(int64_t v) {
#ifdef JANET_INT_TYPES
    return janet_wrap_s64(v);
#else
    return janet_wrap_number((double) v);
#endif
}
static Janet ffi_box_u64(uint64_t v) {
#ifdef JANET_INT_TYPES
    return janet_wrap_u64(v);
#else
    return janet_wrap_number((double) v);
#endif
}

/* Identity guard for install: the manifest is keyed by source name, so
 * two modules may declare the same alias name. The defining file's
 * basename disambiguates (paths differ between analysis and image
 * builds; basenames do not). */
static int ffi_alias_source_is(JanetString src, const char *want) {
    if (NULL == src) return 0;
    int32_t n = janet_string_length(src);
    const char *s = (const char *) src;
    int32_t base = 0;
    for (int32_t i = 0; i < n; i++)
        if (s[i] == '/' || s[i] == '\\') base = i + 1;
    int32_t wl = (int32_t) strlen(want);
    return (n - base == wl) && !memcmp(s + base, want, (size_t) wl);
}

